package scan

import (
	"go/ast"
	"go/token"
	"path"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/Dut-YangLiu/kitex-depgraph/internal/model"
)

// Recognising Kitex generated code. Everything here is syntactic, so it works
// on generated code from any Kitex version without type information.
//
// A generated service package (kitex_gen/<namespace>/<service>/) looks like:
//
//	// Code generated by Kitex v0.12.0. DO NOT EDIT.
//	func newServiceInfo(...) *kitex.ServiceInfo {
//		serviceName := "Echo"
//		handlerType := (*api.Echo)(nil)
//		extra := map[string]interface{}{"PackageName": "api"}
//		svcInfo := &kitex.ServiceInfo{ServiceName: serviceName, PayloadCodec: kitex.Thrift, ...}
//	}
//	func (p *kClient) Echo(ctx context.Context, req *api.Request) (r *api.Response, err error) {
//		... p.c.Call(ctx, "echo", &_args, &_result) ...   // "echo" is the IDL (wire) name
//	}
//	type Client interface { Echo(ctx, req, ...callopt.Option) (*api.Response, error) }  // client.go
//	func NewClient(destService string, opts ...client.Option) (Client, error)           // client.go
//	func NewServer(handler api.Echo, opts ...server.Option) server.Server               // server.go
//
// The identity of the IDL service is PackageName + "." + ServiceName. It is the
// same in every copy generated from the same IDL, whichever repository the
// copy lives in, so it is the join key across repositories.

const (
	genKitex    = "kitex"
	genThriftgo = "thriftgo"
	genOther    = "other"
)

var (
	kitexHeaderRe = regexp.MustCompile(`Code generated by Kitex (v[0-9][^\s]*?)\.?\s+DO NOT EDIT`)
	anyGenRe      = regexp.MustCompile(`(?m)^//\s*Code generated .*DO NOT EDIT`)
)

// classifyHeader inspects the comment block before the package clause.
func classifyHeader(text string) (kind, version string) {
	if strings.HasPrefix(text, "package ") {
		return "", ""
	}
	if i := strings.Index(text, "\npackage "); i >= 0 {
		text = text[:i]
	}
	if m := kitexHeaderRe.FindStringSubmatch(text); m != nil {
		return genKitex, m[1]
	}
	if strings.Contains(text, "Code generated by thriftgo") {
		return genThriftgo, ""
	}
	if anyGenRe.MatchString(text) {
		return genOther, ""
	}
	return "", ""
}

// genHeader summarises the generated-code headers of a package.
type genHeader struct {
	kitex        bool // Kitex / thriftgo generated, or generated code below a gen dir
	kitexVersion string
	generated    int
	total        int
}

func detectGen(files []*ast.File, importPath string, genDirs []string) genHeader {
	var g genHeader
	g.total = len(files)
	for _, f := range files {
		var b strings.Builder
		for _, cg := range f.Comments {
			if cg.Pos() >= f.Package {
				break
			}
			for _, c := range cg.List {
				b.WriteString(c.Text)
				b.WriteByte('\n')
			}
		}
		kind, ver := classifyHeader(b.String())
		if kind != "" {
			g.generated++
		}
		switch kind {
		case genKitex:
			g.kitex = true
			if g.kitexVersion == "" {
				g.kitexVersion = ver
			}
		case genThriftgo:
			g.kitex = true
		}
	}
	if g.generated > 0 {
		for _, seg := range strings.Split(importPath, "/") {
			for _, d := range genDirs {
				if seg == d {
					g.kitex = true
				}
			}
		}
	}
	return g
}

// svcInfo is what a Kitex service package tells about its IDL service.
type svcInfo struct {
	packageName   string
	serviceName   string
	key           string
	kitexVersion  string
	codec         string
	idlFile       string
	handlerType   string
	methods       []model.Method
	goToWire      map[string]string
	clientMethods map[string]bool
}

func (s *svcInfo) wire(goName string) string {
	if w, ok := s.goToWire[goName]; ok {
		return w
	}
	return goName
}

func (s *svcInfo) hasWire(wire string) bool {
	for _, m := range s.methods {
		if m.Wire == wire {
			return true
		}
	}
	return false
}

// extractService returns nil when the package is not a Kitex service package
// (for example the kitex_gen/<namespace> package holding the IDL types).
func extractService(p *lpkg) *svcInfo {
	si := &svcInfo{goToWire: map[string]string{}, clientMethods: map[string]bool{}}
	var clientOrder, mapWire []string
	hasCtor := false
	for _, f := range p.files {
		for _, decl := range f.Decls {
			switch d := decl.(type) {
			case *ast.FuncDecl:
				if d.Recv == nil {
					if d.Name.Name == "NewClient" || d.Name.Name == "NewServer" {
						hasCtor = true
					}
					continue
				}
				if recvBaseName(d.Recv) == "kClient" && d.Body != nil {
					w := wireNameIn(d.Body)
					if w == "" {
						w = d.Name.Name
					}
					si.goToWire[d.Name.Name] = w
				}
			case *ast.GenDecl:
				if d.Tok != token.TYPE {
					continue
				}
				for _, spec := range d.Specs {
					ts, ok := spec.(*ast.TypeSpec)
					if !ok || ts.Name.Name != "Client" {
						continue
					}
					if it, ok := ts.Type.(*ast.InterfaceType); ok && it.Methods != nil {
						for _, m := range it.Methods.List {
							for _, n := range m.Names {
								if !si.clientMethods[n.Name] {
									si.clientMethods[n.Name] = true
									clientOrder = append(clientOrder, n.Name)
								}
							}
						}
					}
				}
			}
		}
		ast.Inspect(f, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.AssignStmt:
				if len(x.Lhs) != 1 || len(x.Rhs) != 1 {
					break
				}
				id, ok := x.Lhs[0].(*ast.Ident)
				if !ok {
					break
				}
				switch id.Name {
				case "serviceName":
					if s, ok := stringLit(x.Rhs[0]); ok && si.serviceName == "" {
						si.serviceName = s
					}
				case "handlerType":
					if si.handlerType == "" {
						si.handlerType = handlerTypeName(x.Rhs[0])
					}
				}
			case *ast.KeyValueExpr:
				switch k := x.Key.(type) {
				case *ast.BasicLit:
					key, ok := stringLit(k)
					if !ok {
						break
					}
					switch key {
					case "PackageName":
						if s, ok := stringLit(x.Value); ok {
							si.packageName = s
						}
					case "ServiceFilePath":
						if s, ok := stringLit(x.Value); ok {
							si.idlFile = s
						}
					default:
						if call, ok := x.Value.(*ast.CallExpr); ok && funcName(call.Fun) == "NewMethodInfo" {
							mapWire = append(mapWire, key)
						}
					}
				case *ast.Ident:
					switch k.Name {
					case "ServiceName":
						if s, ok := stringLit(x.Value); ok && si.serviceName == "" {
							si.serviceName = s
						}
					case "PayloadCodec":
						if sel, ok := x.Value.(*ast.SelectorExpr); ok {
							si.codec = sel.Sel.Name
						}
					case "KiteXGenVersion":
						if s, ok := stringLit(x.Value); ok {
							si.kitexVersion = s
						}
					}
				}
			}
			return true
		})
	}
	if si.serviceName == "" || (!hasCtor && len(si.clientMethods) == 0) {
		return nil
	}
	if si.kitexVersion == "" {
		si.kitexVersion = p.gen.kitexVersion
	}
	if si.packageName == "" {
		if i := strings.LastIndex(si.handlerType, "."); i > 0 {
			si.packageName = si.handlerType[:i]
		} else {
			si.packageName = path.Base(path.Dir(p.importPath))
		}
	}
	si.key = si.packageName + "." + si.serviceName

	order := clientOrder
	if len(order) == 0 {
		for g := range si.goToWire {
			order = append(order, g)
		}
		sort.Strings(order)
	}
	seenWire := map[string]bool{}
	for _, g := range order {
		w := si.goToWire[g]
		if w == "" {
			for _, mw := range mapWire {
				if strings.EqualFold(mw, g) || exportName(mw) == g {
					w = mw
					break
				}
			}
			if w == "" {
				w = g
			}
			si.goToWire[g] = w
		}
		if seenWire[w] {
			continue
		}
		seenWire[w] = true
		si.methods = append(si.methods, model.Method{Go: g, Wire: w})
	}
	for _, mw := range mapWire {
		if !seenWire[mw] {
			seenWire[mw] = true
			si.methods = append(si.methods, model.Method{Go: exportName(mw), Wire: mw})
		}
	}
	return si
}

func recvBaseName(fl *ast.FieldList) string {
	if fl == nil || len(fl.List) == 0 {
		return ""
	}
	t := fl.List[0].Type
	if st, ok := t.(*ast.StarExpr); ok {
		t = st.X
	}
	if id, ok := t.(*ast.Ident); ok {
		return id.Name
	}
	return ""
}

// wireNameIn finds the IDL method name a kClient method sends:
// p.c.Call(ctx, "echo", ...) or a streaming variant.
func wireNameIn(body *ast.BlockStmt) string {
	found := ""
	ast.Inspect(body, func(n ast.Node) bool {
		if found != "" {
			return false
		}
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		name := funcName(call.Fun)
		if name != "Call" && !strings.HasPrefix(name, "Stream") && name != "InvokeStream" {
			return true
		}
		for _, a := range call.Args {
			if s, ok := stringLit(a); ok {
				found = s
				return false
			}
		}
		return true
	})
	return found
}

func funcName(e ast.Expr) string {
	switch x := e.(type) {
	case *ast.SelectorExpr:
		return x.Sel.Name
	case *ast.Ident:
		return x.Name
	}
	return ""
}

// handlerTypeName turns (*api.Echo)(nil) into "api.Echo".
func handlerTypeName(e ast.Expr) string {
	call, ok := e.(*ast.CallExpr)
	if !ok {
		return ""
	}
	t := call.Fun
	if p, ok := t.(*ast.ParenExpr); ok {
		t = p.X
	}
	if s, ok := t.(*ast.StarExpr); ok {
		t = s.X
	}
	switch x := t.(type) {
	case *ast.SelectorExpr:
		if id, ok := x.X.(*ast.Ident); ok {
			return id.Name + "." + x.Sel.Name
		}
	case *ast.Ident:
		return x.Name
	}
	return ""
}

func stringLit(e ast.Expr) (string, bool) {
	bl, ok := e.(*ast.BasicLit)
	if !ok || bl.Kind != token.STRING {
		return "", false
	}
	s, err := strconv.Unquote(bl.Value)
	if err != nil {
		return "", false
	}
	return s, true
}

// exportName mirrors how Kitex names Go methods after IDL methods:
// get_user -> GetUser, echo -> Echo.
func exportName(s string) string {
	var b strings.Builder
	upper := true
	for _, r := range s {
		if r == '_' {
			upper = true
			continue
		}
		if upper && 'a' <= r && r <= 'z' {
			r -= 'a' - 'A'
		}
		upper = false
		b.WriteRune(r)
	}
	return b.String()
}
